-- Additive migration for robust (median/MAD, recency-weighted) reference stats.
-- NOT applied automatically. Run after the base schema and after seeding.
begin;
alter table public.price_reference_stats
  add column if not exists mad_price_egp numeric check (mad_price_egp is null or mad_price_egp >= 0),
  add column if not exists real_sample_count int check (real_sample_count is null or real_sample_count >= 0),
  add column if not exists synthetic_sample_count int check (synthetic_sample_count is null or synthetic_sample_count >= 0),
  add column if not exists effective_sample_size numeric,
  add column if not exists decay_tau_days numeric check (decay_tau_days is null or decay_tau_days > 0);

